import type { Hooks as V1Hooks, Plugin as V1Plugin } from "@opencode-ai/plugin"
import type { Plugin as V2 } from "@opencode/plugin"
import { spawn, spawnSync } from "child_process"
import { appendFileSync, mkdirSync, renameSync, statSync } from "fs"
import { homedir } from "os"
import { join } from "path"

// One module serves both plugin APIs. OpenCode 2.x loads `id` and `setup`;
// OpenCode 1.x calls `server`. The plugin packages are imported for types
// only, so neither is needed at runtime.

const ID = "shmem-opencode"
const RESUBSCRIBE_MS = 1_000

// shmemRoot is the data root `shmem install` wrote into shmem's MCP entry
// when it was a custom one: `--root DIR` in its command, or, from older
// installs, SHMEM_ROOT in its environment. OpenCode runs this plugin with
// its own environment, which lacks a SHMEM_ROOT set only for install, so
// the hooks take the root from the config instead. It is passed as an
// environment variable rather than `--root`, which older shmem binaries
// reject.
let shmemRoot: string | undefined

type MCPEntry = { type?: string; command?: string[]; environment?: Record<string, string> }

function rootFrom(entry: MCPEntry | undefined) {
  if (entry?.type === "local") {
    shmemRoot = rootArg(entry.command ?? []) || entry.environment?.SHMEM_ROOT || undefined
  }
}

// rootArg is the value of --root (or --root=) in an MCP command line.
function rootArg(command: string[]): string | undefined {
  for (let i = 1; i < command.length; i++) {
    const a = command[i]
    if (a === "--") return undefined
    if (a.startsWith("--root=")) return a.slice("--root=".length)
    if (a === "--root" && i + 1 < command.length) return command[i + 1]
  }
  return undefined
}

// AGENT labels what this plugin captures. Claude Code and Codex hooks pass
// --caller-agent; it is set in the environment here instead, which every
// shmem binary reads, and which OpenCode's own environment would otherwise
// leave to detection: "cli" from a shell, "claude-code" inside Claude Code.
const AGENT = "opencode"

// SHMEM_HOOK_DEDUP=off: shmem hook's dedup matches its argv against Claude
// Code's settings files to skip a duplicate Claude registration. The plugin
// is not one, and a bare `shmem hook <event>` registered at an older Claude
// level would match it and skip the capture silently. OpenCode has one
// registration, the plugin, so there is nothing to dedup.
function hookEnv(): NodeJS.ProcessEnv {
  const env: NodeJS.ProcessEnv = { ...process.env, SHMEM_CALLER_AGENT: AGENT, SHMEM_HOOK_DEDUP: "off" }
  if (shmemRoot && !process.env.SHMEM_ROOT) env.SHMEM_ROOT = shmemRoot
  return env
}

// recordFailure appends a capture failure to hook-errors.log in the shmem
// root, which `shmem admin status` reports. It is the one channel both
// plugin APIs have: OpenCode 2.x shows plugins' output nowhere and has no
// log call, and a hook that throws blocks the prompt. Written with fs, not
// shmem, so it works when the binary is what's missing.
const ERRORS_FILE = "hook-errors.log"
const ERRORS_MAX_BYTES = 256 * 1024

function recordFailure(message: string): void {
  try {
    // The same precedence as hookEnv, so the log lands in the root the
    // hooks write to and status reads: the environment's, then install's.
    const root = process.env.SHMEM_ROOT || shmemRoot || join(homedir(), ".shmem")
    const path = join(root, ERRORS_FILE)
    // Private, as SECURITY.md has shmem's data: directories 0700, files 0600.
    mkdirSync(root, { recursive: true, mode: 0o700 })
    try {
      if (statSync(path).size > ERRORS_MAX_BYTES) renameSync(path, `${path}.1`)
    } catch {
      // no file yet
    }
    appendFileSync(path, `${new Date().toISOString()}\t${AGENT}\t${message.replace(/\s+/g, " ")}\n`, { mode: 0o600 })
  } catch {
    // nowhere left to report to
  }
}

// report surfaces a capture failure. Failures never interrupt OpenCode, but
// they must not vanish either: a capture that stops working otherwise looks
// exactly like one that works. The 1.x server adds OpenCode's log and a toast.
let report = (message: string): void => {
  recordFailure(message)
  console.error(`${ID}: ${message}`)
}

// SKIPPED starts the line shmem hook prints when it drops a capture it was
// given (cli/hook.go).
const SKIPPED = "shmem: warning [hook]:"

const HOOK_TIMEOUT_MS = 10_000

// checkHook reports a hook run that failed: a spawn error, a non-zero
// exit, or shmem hook's own skip line. shmem hook exits 0 even when it
// skips a capture, and says why on stderr; other stderr on success is
// ordinary notices (a new release, a first-run message), not failures.
function checkHook(what: string, error: Error | undefined, status: number | null, signal: string | null, stderr: string) {
  stderr = stderr.trim()
  if (error) report(`${what} failed: ${error.message}`)
  else if (status !== 0) report(`${what} exited ${status ?? signal}${stderr ? `: ${stderr}` : ""}`)
  else {
    for (const line of stderr.split("\n")) {
      if (line.startsWith(SKIPPED)) report(`${what}: ${line}`)
    }
  }
}

// shmemHook runs `shmem hook <subcommand>`, waits for it, and returns what
// it printed. It blocks OpenCode's one JS thread, so it is kept for the
// prompt, whose hook must finish (and hand back its context) before the
// turn goes on.
function shmemHook(subcommand: string, payload: Record<string, unknown>): string {
  const what = `shmem hook ${subcommand}`
  try {
    const run = spawnSync("shmem", ["hook", subcommand], {
      input: JSON.stringify(payload),
      timeout: HOOK_TIMEOUT_MS,
      stdio: ["pipe", "pipe", "pipe"],
      encoding: "utf8",
      env: hookEnv(),
    })
    checkHook(what, run.error, run.status, run.signal, run.stderr ?? "")
    // stdout even on failure: the hook hands out its context before it
    // saves, so a failed save can still have printed context that shmem
    // won't hand out again. hookContext ignores anything that isn't it.
    return run.stdout ?? ""
  } catch (err) {
    report(`${what} failed: ${err instanceof Error ? err.message : String(err)}`)
    return ""
  }
}

// hookContext is the additionalContext in `shmem hook user-message`'s
// output: the signed-out reminder and share updates, which Claude Code adds
// to the turn. shmem hands each one out once, so whatever comes back here
// must reach the model or it is lost.
function hookContext(stdout: string): string {
  if (!stdout.trim()) return ""
  try {
    const ctx = JSON.parse(stdout)?.hookSpecificOutput?.additionalContext
    return typeof ctx === "string" ? ctx : ""
  } catch {
    return ""
  }
}

// turnContext holds each session's hook context for its current turn. Every
// model request of the turn gets it, not just the first, since a turn that
// starts with a tool call answers the user in a later request. The next
// prompt replaces it once a request has carried it; until then, as when
// prompts are queued behind a running turn, the next prompt's context is
// added to it.
const turnContext = new Map<string, { text: string; delivered: boolean }>()

function contextFor(sessionID: string | undefined): string {
  const ctx = sessionID ? turnContext.get(sessionID) : undefined
  if (!ctx) return ""
  ctx.delivered = true
  return ctx.text
}

function setTurnContext(sessionID: string, text: string) {
  const prev = turnContext.get(sessionID)
  const waiting = prev && !prev.delivered ? prev.text : ""
  const joined = [waiting, text].filter(Boolean).join("\n\n")
  if (joined) turnContext.set(sessionID, { text: joined, delivered: false })
  else turnContext.delete(sessionID)
}

// shmemHookAsync runs `shmem hook <subcommand>` without waiting, for
// replies and tool calls: an agent turn can make dozens of tool calls, and
// waiting on each would stall OpenCode's streaming and UI every time.
function shmemHookAsync(subcommand: string, payload: Record<string, unknown>): void {
  const what = `shmem hook ${subcommand}`
  try {
    // Detached, so the capture finishes when OpenCode exits right after the
    // turn (as `opencode run` does): OpenCode 2.x kills its plugins'
    // children on shutdown.
    const child = spawn("shmem", ["hook", subcommand], {
      stdio: ["pipe", "ignore", "pipe"],
      env: hookEnv(),
      detached: true,
    })
    child.unref()
    let stderr = ""
    let failed: Error | undefined
    const timer = setTimeout(() => {
      failed = new Error(`timed out after ${HOOK_TIMEOUT_MS / 1000}s`)
      child.kill()
    }, HOOK_TIMEOUT_MS)
    child.stderr?.setEncoding("utf8").on("data", (chunk: string) => (stderr += chunk))
    child.on("error", (err) => (failed = err))
    child.on("close", (status, signal) => {
      clearTimeout(timer)
      checkHook(what, failed, failed ? null : status, signal, stderr)
    })
    child.stdin?.on("error", () => {})
    child.stdin?.end(JSON.stringify(payload))
  } catch (err) {
    report(`${what} failed: ${err instanceof Error ? err.message : String(err)}`)
  }
}

// What counts as too short to keep is `shmem hook`'s call, as it is for
// every other agent: the plugin passes everything through.
function userMessage(text: string, cwd: string, sessionID: string) {
  setTurnContext(sessionID, text.trim() ? hookContext(shmemHook("user-message", { prompt: text, session_id: sessionID, cwd })) : "")
}

function response(text: string, cwd: string, sessionID: string) {
  if (text.trim()) shmemHookAsync("response", { last_assistant_message: text, session_id: sessionID, cwd })
}

// TOOLS maps OpenCode's tool names (1.x and 2.x) onto the Claude Code names
// `shmem hook tool-use` formats, so a tool fact reads the same from any
// agent, and its input keys onto Claude Code's.
const TOOLS: Record<string, string> = {
  read: "Read",
  edit: "Edit",
  write: "Write",
  bash: "Bash",
  shell: "Bash",
  grep: "Grep",
  glob: "Glob",
  webfetch: "WebFetch",
  websearch: "WebSearch",
  task: "Agent",
  subagent: "Agent",
}

function toolInput(args: Record<string, unknown>): Record<string, unknown> {
  const out: Record<string, unknown> = { ...args }
  const path = args.filePath ?? args.path
  if (path !== undefined) out.file_path = path
  return out
}

// toolResponse is what `shmem hook` renders as the fact's body. OpenCode's
// edit and write tools answer with a status line ("Edit applied
// successfully."); the change itself is in their input. They get the object
// shape Claude Code's Edit and Write results have, which the hook renders
// as the old and new text, or the content written.
function toolResponse(tool: string, args: Record<string, unknown>, output: string): unknown {
  const filePath = args.filePath ?? args.path
  if (tool === "edit" && typeof args.oldString === "string" && typeof args.newString === "string")
    return { filePath, oldString: args.oldString, newString: args.newString }
  if (tool === "write" && typeof args.content === "string") return { filePath, content: args.content }
  return output
}

// toolUse captures one finished tool call. shmem's own MCP tools are left
// out, as `shmem hook` leaves out shmem's own CLI calls.
function toolUse(
  tool: string,
  args: Record<string, unknown> | undefined,
  output: string,
  callID: string,
  sessionID: string,
  cwd: string,
) {
  if (/shmem/i.test(tool)) return
  shmemHookAsync("tool-use", {
    tool_name: TOOLS[tool] ?? tool,
    tool_input: toolInput(args ?? {}),
    tool_response: toolResponse(tool, args ?? {}, output),
    tool_use_id: callID,
    session_id: sessionID,
    cwd,
  })
}

// OpenCode 2.x.
async function setup(ctx: V2.Context): Promise<V2.Cleanup> {
  const cwd = ctx.location.directory
  await ctx.mcp.transform((mcp) => rootFrom(mcp.get("shmem")))
  await ctx.session.hook("prompt", (input) => userMessage(input.prompt.text, cwd, input.sessionID))
  await ctx.session.hook("context", (input) => {
    const extra = contextFor(input.sessionID)
    if (extra) input.system.push({ type: "text", text: extra })
  })

  // A reply's text arrives whole in session.text.ended, the 2.x counterpart
  // of the finished text parts 1.x captures from its event stream. A tool call arrives in three
  // events with one id: its name, then its input, then its result.
  // The stream can error or end while OpenCode keeps running; subscribe again
  // after a pause, so replies don't stop being captured until a restart.
  // Only cleanup (the abort) ends it. Errors never reach OpenCode.
  const controller = new AbortController()
  const { signal } = controller
  const calls = new Map<string, { name?: string; input?: Record<string, unknown> }>()
  const types = [
    "session.text.ended",
    "session.tool.input.started",
    "session.tool.called",
    "session.tool.success",
    "session.tool.failed",
  ] as const
  void (async () => {
    while (!signal.aborted) {
      try {
        for await (const event of ctx.event.subscribe({ types: [...types], signal })) {
          switch (event.type) {
            case "session.text.ended":
              response(event.data.text, cwd, event.data.sessionID)
              break
            case "session.tool.input.started":
              calls.set(event.data.id, { name: event.data.name })
              break
            case "session.tool.called":
              calls.set(event.data.id, { ...calls.get(event.data.id), input: { ...event.data.input } })
              break
            case "session.tool.success": {
              const call = calls.get(event.data.id)
              calls.delete(event.data.id)
              if (!call?.name) break
              toolUse(call.name, call.input, contentText(event.data.content), event.data.id, event.data.sessionID, cwd)
              break
            }
            case "session.tool.failed":
              // Claude Code's PostToolUse fires on success only.
              calls.delete(event.data.id)
              break
          }
        }
      } catch {
        // fall through to resubscribe
      }
      if (!signal.aborted) await new Promise((resolve) => setTimeout(resolve, RESUBSCRIBE_MS))
    }
  })()
  return () => controller.abort()
}

// contentText renders MCP-style content blocks: text joined, anything else
// as a placeholder naming it.
function contentText(content: ReadonlyArray<{ type: string; text?: string; name?: string; uri?: string }>): string {
  return content.map((c) => (c.type === "text" ? (c.text ?? "") : `[${c.type}: ${c.name ?? c.uri ?? ""}]`)).join("\n")
}

// toolOutputV1 is a 1.x tool's result. Built-in tools give a string
// `output`; an MCP tool can hand back its content blocks instead.
function toolOutputV1(output: unknown): string {
  const o = output as { output?: unknown; content?: unknown }
  if (typeof o?.output === "string") return o.output
  if (Array.isArray(o?.content)) return contentText(o.content)
  return output === undefined ? "" : JSON.stringify(output)
}

// OpenCode 1.x.
const server: V1Plugin = async ({ directory, client }) => {
  let toasted = false
  report = (message) => {
    recordFailure(message)
    console.error(`${ID}: ${message}`)
    void client.app.log({ body: { service: ID, level: "warn", message } }).catch(() => {})
    // One toast per OpenCode run: enough to be noticed, not one per turn.
    if (!toasted) {
      toasted = true
      void client.tui
        .showToast({ body: { title: "shmem", message: `Memory capture failed: ${message}`, variant: "warning" } })
        .catch(() => {})
    }
  }
  return hooksV1(directory)
}

// A 1.x reply is captured from the stable event stream: a text part whose
// time.end is set has finished, and message.updated says which messages
// are the assistant's. Parts are sent once each, since part.updated can
// repeat for a finished part.
type V1Event = Parameters<NonNullable<V1Hooks["event"]>>[0]["event"]

// replyEvents only counts replies being generated: a message first seen already
// completed is a copy (a forked session re-emits every earlier message under
// new ids), and was captured when it was written. A message's state is
// dropped when it completes, so a long-running OpenCode keeps none per reply.
function replyEvents(directory: string) {
  const live = new Map<string, Set<string>>() // message id -> text parts sent
  return async ({ event }: { event: V1Event }) => {
    if (event.type === "message.updated") {
      const info = event.properties.info
      if (info.role !== "assistant") return
      if (info.time.completed !== undefined) live.delete(info.id)
      else if (!live.has(info.id)) live.set(info.id, new Set())
      return
    }
    if (event.type !== "message.part.updated") return
    const part = event.properties.part
    if (part.type !== "text" || part.synthetic || part.time?.end === undefined) return
    const sent = live.get(part.messageID)
    if (!sent || sent.has(part.id)) return
    sent.add(part.id)
    response(part.text, directory, part.sessionID)
  }
}

const hooksV1 = (directory: string): Awaited<ReturnType<V1Plugin>> => ({
  event: replyEvents(directory),

  config: async (config) => rootFrom(config.mcp?.shmem),

  "chat.message": async (input, output) => {
    const text = output.parts
      .filter((p): p is Extract<typeof p, { type: "text" }> => p.type === "text")
      .map((p) => p.text)
      .join("")
    userMessage(text, directory, input.sessionID)
  },

  // The 1.x counterpart of 2.x's context hook: the only place a plugin can
  // add to the model's instructions for a request.
  "experimental.chat.system.transform": async (input, output) => {
    const extra = contextFor(input.sessionID)
    if (extra) output.system.push(extra)
  },

  "tool.execute.after": async (input, output) => {
    toolUse(input.tool, input.args, toolOutputV1(output), input.callID, input.sessionID, directory)
  },
})

export default {
  id: ID,
  setup,
  server,
} satisfies V2.Plugin & { server: V1Plugin }
